document.querySelectorAll("[data-spenden] [data-copy]").forEach(function(t){const e=t.querySelector("span"),o=e.textContent;let n;t.addEventListener("click",function(){const c=function(){e.textContent=t.dataset.copied,clearTimeout(n),n=setTimeout(function(){e.textContent=o},2500)};if(navigator.clipboard&&window.isSecureContext)return void navigator.clipboard.writeText(t.dataset.copy).then(c);const a=document.createElement("textarea");a.value=t.dataset.copy,a.setAttribute("readonly",""),a.style.position="fixed",a.style.opacity="0",document.body.append(a),a.select(),document.execCommand("copy"),a.remove(),c()})});